	case XDP_TX:
		ret = fec_enet_xdp_tx_xmit(fep->netdev, xdp);
		if (ret == FEC_ENET_XDP_CONSUMED) {
			page = virt_to_head_page(xdp->data);
			page_pool_put_page(rxq->page_pool, page, sync, true);
		} else {
			ret = FEC_ENET_XDP_TX;
		}
		break;
	case XDP_ABORTED:
		fallthrough;    /* handle aborts by dropping packet */

	case XDP_DROP:
